CONST BASE=$10;

MAIN()
{
  CONST STEP=3;
  VAR A;
  A=BASE+STEP;
  PRINT(HEX2$(A), /);
}

CONST X=5;

TWICE(X)
{
  RETURN(X*2);
}

MAIN()
{
  PRINT(TWICE(3), " ", X, /);
}

MACHINE ASMFUNC(1):ASMROUTINE;

MAIN()
{
  PRINT(ASMFUNC(100), /);
}

#ASM
ASMROUTINE:
  LD DE,123
  ADD HL,DE
  RET
#END

MAIN()
{
  VAR I, J;
  FOR I=1 TO 3
  {
    FOR J=1 TO 3
    {
      IF I*J==4 THEN EXIT(2);
      PRINT(I*J, " ");
    }
  }
  PRINT(/, I, ",", J, /);
}

MAIN()
{
  VAR FLOAT F;
  F=2.5;
  PRINT("VALUE\N", FL$(F), " ", HEX2$($41), /);
  PRINT("A\NB\0C", /);
}

MAIN()
{
  VAR RESULT;
  RESULT=FOPEN(0, "A:DATA.BIN", 0);
  IF RESULT==0 THEN FCLOSE(0);
  PRINT(RESULT, /);
}

VAR FRAME;

VSYNC_PROC()
{
  FRAME=FRAME+1;
}

MAIN()
{
  VAR KEY;
  LOOP
  {
    KEY=INKEY(0);
    LOCATE(0,0);
    PRINT(FRAME, " KEY=", KEY, "   ");
    VSYNC(1);
  }
}

MAIN()
{
  WIDTH(40);
  LOCATE(10, 5);
  IF TATTR($27) THEN PRINT(CHR$(128));
}

MAIN()
{
  VAR FLOAT VALUE;
  VALUE=FSQRT(81.0);
  PRINT(FL$(VALUE), /);
}

MAIN()
{
  VAR OLD, NEW, PRESSED;
  OLD=STICK(0);
  LOOP
  {
    NEW=STICK(0);
    PRESSED=(NEW XOR OLD) AND OLD;
    IF PRESSED!=0 THEN PRINT(HEX2$(PRESSED), /);
    OLD=NEW;
  }
}
